import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Search, MapPin, ArrowRight, Star, Clock, ChevronRight, Flame } from "lucide-react";
import DishArt from "../components/DishArt";
import ThaliOrbit from "../components/ThaliOrbit";
import Tilt3D from "../components/Tilt3D";
import { api } from "../api/client";

const currency = (n) => `₹${n.toFixed(0)}`;

const QUICK_CATEGORIES = [
  { label: "Breakfast & Tiffin", tag: "Breakfast & Tiffin" },
  { label: "Rice", tag: "Rice" },
  { label: "Kuzhambu & Curries", tag: "Kuzhambu & Curries" },
  { label: "Non-Veg Specials", tag: "Non-Veg Specials" },
  { label: "Sweets", tag: "Sweets" },
];

export default function Home() {
  const [featured, setFeatured] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    api
      .getMenu()
      .then((items) => setFeatured(items.slice(0, 6)))
      .catch((err) => setError(err.message));
  }, []);

  return (
    <main>
      {/* ---- Search-driven hero ---- */}
      <section style={{ background: "var(--night)", position: "relative" }}>
        <div className="container" style={{ padding: "48px 24px 40px", textAlign: "center" }}>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 6, color: "#D0D0D0", fontSize: 13, fontWeight: 600, marginBottom: 14 }}>
            <MapPin size={15} color="var(--chili)" /> Delivering to your area
          </div>
          <h1 className="disp" style={{ fontSize: "clamp(30px, 4vw, 42px)", lineHeight: 1.15, color: "#FFFFFF", fontWeight: 700, margin: 0 }}>
            Authentic Tamil Nadu food,
            <br />
            tracked to your door
          </h1>

          <div
            style={{
              maxWidth: 560,
              margin: "28px auto 0",
              background: "var(--card)",
              borderRadius: 12,
              padding: "4px 4px 4px 16px",
              display: "flex",
              alignItems: "center",
              gap: 10,
              boxShadow: "0 12px 30px rgba(0,0,0,0.28)",
            }}
          >
            <Search size={18} color="var(--ink-faint)" />
            <input
              placeholder="Search for dosa, sambar, biryani…"
              style={{ flex: 1, border: "none", outline: "none", fontSize: 15, padding: "12px 0", color: "var(--ink)" }}
              readOnly
            />
            <Link
              to="/menu"
              className="focus-ring"
              style={{ background: "var(--chili)", color: "#FFFFFF", border: "none", borderRadius: 8, padding: "12px 20px", fontSize: 14, fontWeight: 700, display: "flex", alignItems: "center", gap: 6, whiteSpace: "nowrap" }}
            >
              Search
            </Link>
          </div>

          <div style={{ display: "flex", gap: 10, justifyContent: "center", marginTop: 22, flexWrap: "wrap" }}>
            {QUICK_CATEGORIES.map((c) => (
              <Link
                key={c.tag}
                to="/menu"
                className="focus-ring"
                style={{
                  background: "var(--night-2)",
                  border: "1px solid var(--border-dark)",
                  color: "#FFFFFF",
                  borderRadius: 999,
                  padding: "8px 16px",
                  fontSize: 13.5,
                  fontWeight: 600,
                }}
              >
                {c.label}
              </Link>
            ))}
          </div>

          <div style={{ display: "flex", gap: 28, justifyContent: "center", marginTop: 30, flexWrap: "wrap" }}>
            <Stat value="4.9" label="Average rating" icon={<Star size={16} color="var(--marigold)" fill="var(--marigold)" />} />
            <Stat value="27 min" label="Avg. delivery time" icon={<Clock size={16} color="var(--chili)" />} />
            <Stat value="2,300+" label="Orders this month" icon={<ArrowRight size={16} color="var(--curry)" />} />
          </div>

          <div style={{ marginTop: 36 }}>
            <ThaliOrbit size={200} />
          </div>
        </div>
        <svg className="leaf-edge" viewBox="0 0 1200 34" preserveAspectRatio="none" aria-hidden="true">
          <path
            d="M0,34 L0,10 Q30,0 60,9 Q90,18 120,7 Q150,-2 180,10 Q210,22 240,8 Q270,-4 300,9 Q330,20 360,6 Q390,-6 420,11 Q450,22 480,7 Q510,-3 540,10 Q570,20 600,6 Q630,-6 660,11 Q690,22 720,7 Q750,-3 780,10 Q810,20 840,6 Q870,-6 900,11 Q930,22 960,7 Q990,-3 1020,10 Q1050,20 1080,6 Q1110,-6 1140,11 Q1170,22 1200,10 L1200,34 Z"
            fill="var(--paper)"
          />
        </svg>
      </section>

      {/* ---- Featured dishes grid, restaurant-card style ---- */}
      <section className="container" style={{ padding: "44px 24px 80px" }}>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 20 }}>
          <h2 className="disp" style={{ fontSize: 22, color: "var(--ink)", fontWeight: 700, margin: 0 }}>
            Popular right now
          </h2>
          <Link to="/menu" className="focus-ring" style={{ color: "var(--chili)", fontWeight: 700, fontSize: 14, display: "flex", gap: 4, alignItems: "center" }}>
            See full menu <ChevronRight size={15} />
          </Link>
        </div>

        {error && (
          <div style={{ background: "#FBEAD8", border: "1px solid rgba(203,32,45,0.25)", color: "var(--chili)", borderRadius: 10, padding: 16, fontSize: 14 }}>
            Couldn't load the menu ({error}). Make sure the backend API is running and seeded.
          </div>
        )}

        {!error && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 18 }}>
            {featured.map((item, idx) => (
              <Tilt3D key={item._id}>
              <div
                className="dish-card"
                style={{
                  background: "var(--card)",
                  borderRadius: 12,
                  overflow: "hidden",
                  border: "1px solid var(--border)",
                  boxShadow: "0 1px 3px rgba(0,0,0,0.04)",
                }}
              >
                <div style={{ position: "relative" }}>
                  <DishArt seed={idx} image={item.image} />
                  <div
                    className="mono"
                    style={{
                      position: "absolute",
                      top: 10,
                      left: 10,
                      background: "var(--curry)",
                      color: "#FFFFFF",
                      borderRadius: 6,
                      padding: "3px 7px",
                      fontSize: 12,
                      display: "flex",
                      alignItems: "center",
                      gap: 4,
                    }}
                  >
                    <Star size={11} fill="#FFFFFF" /> 4.{3 + (idx % 6)}
                  </div>
                </div>
                <div style={{ padding: 14 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    {item.tags?.[0] && (
                      <span style={{ fontSize: 10.5, fontWeight: 800, color: "var(--marigold)", letterSpacing: "0.04em" }}>
                        {item.tags[0].toUpperCase()}
                      </span>
                    )}
                    <span style={{ fontSize: 11, color: "var(--ink-faint)", display: "flex", alignItems: "center", gap: 3 }}>
                      <Flame size={11} /> {item.calories} kcal
                    </span>
                  </div>
                  <div className="disp" style={{ fontSize: 15.5, fontWeight: 600, color: "var(--ink)", marginTop: 5 }}>
                    {item.name}
                  </div>
                  <div style={{ fontSize: 13, color: "var(--ink-faint)", marginTop: 3, minHeight: 32 }}>{item.description}</div>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 10 }}>
                    <span className="mono" style={{ fontWeight: 700, color: "var(--ink)", fontSize: 15 }}>{currency(item.price)}</span>
                    <span style={{ fontSize: 12, color: "var(--ink-faint)", fontWeight: 600 }}>25–30 min</span>
                  </div>
                </div>
              </div>
              </Tilt3D>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}

function Stat({ value, label, icon }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      {icon}
      <div style={{ textAlign: "left" }}>
        <div style={{ fontSize: 15, fontWeight: 700, color: "#FFFFFF" }}>{value}</div>
        <div style={{ fontSize: 11.5, color: "#9C9C9C" }}>{label}</div>
      </div>
    </div>
  );
}
